css:
/* From Uiverse.io by cbolson  - Tags: checkbox */
.__UIV_SCOPE__ .my-form {
  --_clr-primary: #666;
  --_clr-hover: #f33195;
  --_clr-checked: #127acf;
}
.__UIV_SCOPE__ .my-form > div {
  --_clr-current: var(--_clr-primary);

  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.__UIV_SCOPE__ .my-form > div + div {
  margin-block-start: 0.5rem;
}
.__UIV_SCOPE__ .my-form label {
  cursor: pointer;
  color: var(--_clr-current);
  transition: color 150ms ease-in-out;
}

/* styled checkbox */
.__UIV_SCOPE__ .my-form input[type="checkbox"] {
  appearance: none;
  outline: none;
  width: 1.5rem;
  height: 1.5rem;
  aspect-ratio: 1;
  padding: 0.25rem;
  background: transparent;
  border: 1px solid var(--_clr-current);
  border-radius: 2px;
  display: grid;
  place-content: center;
  cursor: pointer;
}
.__UIV_SCOPE__ .my-form input[type="checkbox"]::after {
  content: "\2714";
  opacity: 0;
  transition: opacity 150ms ease-in-out;
  color: var(--_clr-checked);
  font-size: inherit;
  font-family: inherit;
}

.__UIV_SCOPE__ .my-form label:hover,
.__UIV_SCOPE__ .my-form input[type="checkbox"]:focus-visible,
.__UIV_SCOPE__ .my-form input[type="checkbox"]:focus-visible + label,
.__UIV_SCOPE__ .my-form input[type="checkbox"]:hover,
.__UIV_SCOPE__ .my-form input[type="checkbox"]:hover + label {
  --_clr-current: var(--_clr-hover);
}
.__UIV_SCOPE__ .my-form input[type="checkbox"]:focus-visible::after,
.__UIV_SCOPE__ .my-form input[type="checkbox"]:hover::after {
  opacity: 0.5;
  color: var(--_clr-hover);
}

.__UIV_SCOPE__ .my-form input[type="checkbox"]:checked + label:not(:hover),
.__UIV_SCOPE__ .my-form input[type="checkbox"]:checked:not(:hover) {
  --_clr-current: var(--_clr-checked);
}
.__UIV_SCOPE__ .my-form input[type="checkbox"]:checked::after {
  opacity: 1;
}
